var f=typeof(TalesTactics.CharacterMotion).GetField("started",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
return new{utc=System.DateTime.UtcNow.ToString("o"),playing=UnityEditor.EditorApplication.isPlaying,frame=UnityEngine.Time.frameCount,time=UnityEngine.Time.time,delta=UnityEngine.Time.deltaTime,scale=UnityEngine.Time.timeScale,poses=UnityEngine.Object.FindObjectsByType<TalesTactics.CharacterMotion>(UnityEngine.FindObjectsSortMode.None).Where(m=>m.name.StartsWith("Pose check ")).Select(m=>new{m.name,action=m.Action.ToString(),elapsed=UnityEngine.Time.time-(float)f.GetValue(m),sprite=m.GetComponent<UnityEngine.SpriteRenderer>().sprite?.name}).ToArray()};
